mapper.select:
SELECT 
FROM crane_task
WHERE 1 = 1

    AND request_id = #{requestId}


    AND crane_id = #{craneId}


    AND task_type = #{taskType}


    AND task_status = #{taskStatus}


    AND priority_level = #{priorityLevel}


    AND container_main_id = #{containerMainId}


    AND source_location_id = #{sourceLocationId}


    AND target_location_id = #{targetLocationId}


    AND dispatched_time >= #{dispatchedAfter}


    AND dispatched_time <= #{dispatchedBefore}


    AND completed_time >= #{completedAfter}


    AND completed_time <= #{completedBefore}


    AND cancelled_time >= #{cancelledAfter}


    AND cancelled_time <= #{cancelledBefore}

ORDER BY created_time Desc,id DESC
